-- PostgreSQL schema. Demo season is a fictional January 2025 mini-season.
CREATE TABLE leagues(league_id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL,sport TEXT NOT NULL);
CREATE TABLE teams(team_id INTEGER PRIMARY KEY,league_id INTEGER NOT NULL REFERENCES leagues,name TEXT NOT NULL);
CREATE TABLE players(player_id INTEGER PRIMARY KEY,team_id INTEGER NOT NULL REFERENCES teams,name TEXT NOT NULL);
CREATE TABLE games(game_id INTEGER PRIMARY KEY,league_id INTEGER NOT NULL REFERENCES leagues,game_date DATE NOT NULL,home_team_id INTEGER NOT NULL REFERENCES teams,away_team_id INTEGER NOT NULL REFERENCES teams,home_score INTEGER NOT NULL,away_score INTEGER NOT NULL,CHECK(home_team_id<>away_team_id));
CREATE TABLE nba_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,points INTEGER NOT NULL CHECK(points>=0),rebounds INTEGER NOT NULL CHECK(rebounds>=0),assists INTEGER NOT NULL CHECK(assists>=0),PRIMARY KEY(game_id,player_id));
CREATE TABLE nfl_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,passing_yards INTEGER NOT NULL CHECK(passing_yards>=0),passing_touchdowns INTEGER NOT NULL CHECK(passing_touchdowns>=0),interceptions INTEGER NOT NULL CHECK(interceptions>=0),PRIMARY KEY(game_id,player_id));
CREATE TABLE mlb_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,hits INTEGER NOT NULL CHECK(hits>=0),at_bats INTEGER NOT NULL CHECK(at_bats>=0),home_runs INTEGER NOT NULL CHECK(home_runs>=0),PRIMARY KEY(game_id,player_id));
CREATE TABLE nhl_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,goals INTEGER NOT NULL CHECK(goals>=0),assists INTEGER NOT NULL CHECK(assists>=0),shots INTEGER NOT NULL CHECK(shots>=0),PRIMARY KEY(game_id,player_id));
CREATE TABLE ncaa_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,points INTEGER NOT NULL CHECK(points>=0),rebounds INTEGER NOT NULL CHECK(rebounds>=0),assists INTEGER NOT NULL CHECK(assists>=0),PRIMARY KEY(game_id,player_id));
CREATE TABLE soccer_player_games(game_id INTEGER NOT NULL REFERENCES games,player_id INTEGER NOT NULL REFERENCES players,goals INTEGER NOT NULL CHECK(goals>=0),assists INTEGER NOT NULL CHECK(assists>=0),shots INTEGER NOT NULL CHECK(shots>=0),PRIMARY KEY(game_id,player_id));
